"""Seal the static-only Reader ACL evidence and gate decision."""
import hashlib,json
from verify import evaluate
from derive import O,R,REPORT,rd,git
def put(n,v):(O/n).write_text(json.dumps(v,indent=2)+'\n',encoding='utf-8')
def seal():
    files=[p for p in O.rglob('*') if p.is_file() and p.name!='SHA256-MANIFEST.json']+[REPORT]
    put('SHA256-MANIFEST.json',dict(algorithm='SHA256_CHECKOUT_BYTES',self_excluded=True,files={p.relative_to(R).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(files)}))
def main():
    frozen=rd(O/'baseline-freeze.json');c=rd(O/'acl-completeness.json');invariants=rd(O/'five-invariant-proofs.json')['invariants'];transitive=rd(O/'transitive-authority-proof.json');future=rd(O/'future-implementation-boundary.json');review=rd(O/'independent-review.json');attack=rd(O/'adversarial-review.json');acl=rd(O/'effective-acl-ledger.json')['entries']
    for n in ['gate.json','test-results.json','SHA256-MANIFEST.json']:
        if not (O/n).exists():put(n,{})
    before=set(frozen['untracked_before_paths']);now=set(git('ls-files','--others','--exclude-standard').splitlines());prefix=O.relative_to(R).as_posix()+'/'
    gate=dict(BRANCH=frozen['branch'],BASELINE_HEAD=frozen['head'],CURRENT_HEAD=git('rev-parse','HEAD'),REMOTE_TRACKING_REF_HEAD=git('rev-parse','origin/checkpoint/package-0090-cloud-handoff'),REMOTE_NETWORK_VERIFIED='NO',TRACKED_DIRTY_COUNT=len(git('diff','--name-only').splitlines()),STAGED_COUNT=len(git('diff','--cached','--name-only').splitlines()),UNTRACKED_BEFORE=len(before),UNTRACKED_AFTER=len(now),UNAUTHORIZED_UNTRACKED_COUNT=sum(p not in before and not p.startswith(prefix) and p!=REPORT.relative_to(R).as_posix() for p in now),TARGET_BLOCKERS_REQUIRED=1,TARGET_BLOCKERS_CLOSED=0,N1_CATALOG_EFFECT_GRAPH='CLOSED',N1_READER_EFFECTIVE_ACL='OPEN',READER_PARTICIPANT_ID=future['READER_PARTICIPANT_ID'],READER_PRINCIPAL_ID=future['READER_PRINCIPAL_ID'],READER_AUTHENTICATION_CONTRACT=future['READER_AUTHENTICATION_CONTRACT'],READER_PHYSICAL_AUTH_MECHANISM=future['READER_PHYSICAL_AUTH_MECHANISM'],READER_GRAPH_NODES_REACHABLE=c['reachable_nodes'],READER_GRAPH_EDGES_REACHABLE=c['reachable_edges'],READER_EFFECTIVE_ACL_ENTRIES_TOTAL=len(acl),READER_EFFECTIVE_ACL_RESOLVED=sum(not a['AUTHORITY_CRITICAL_UNRESOLVED'] for a in acl),READER_EFFECTIVE_ACL_UNRESOLVED=sum(a['AUTHORITY_CRITICAL_UNRESOLVED'] for a in acl),TRANSITIVE_AUTHORITY_PATHS_FOUND=len(transitive['forbidden_capability_paths']),TRANSITIVE_AUTHORITY_PATHS_UNRESOLVED=len(transitive['unresolved_edge_ids']),TRANSITIVE_AUTHORITY_PATH_COUNT_SCOPE='FORBIDDEN_OR_ESCALATING_PATHS; permitted typed invocation/data paths retained in proof',READER_ACL_ADVERSARIAL_FINDINGS_OPEN=attack['READER_ACL_ADVERSARIAL_FINDINGS_OPEN'],PHYSICAL_ACL_IMPLEMENTATION_PROOF='FUTURE',RUNTIME_ACL_PROOF='FUTURE',CLOSED_CONTRACTS_REOPENED=0,CONTRADICTIONS_DISCOVERED=0,N1_QUALIFICATION_INPUT_RESOLUTION='OPEN_BY_DEPENDENCY',N1_SUBSTITUTION_STATIC_WITNESSES='OPEN_BY_DEPENDENCY',INDEPENDENT_READER_ACL_REVIEW=review['INDEPENDENT_READER_ACL_REVIEW'],R5N2A4_2_STATUS='PENDING_STATIC_VALIDATION',NEXT_EXECUTED=False,NEXT_GATE='RESOLVE_READER_STATIC_AUTHORITY_DERIVATION',PROOF_SCOPE='ACCEPTED_STATIC_OPERATION_TRANSPORT_CONTRACT_NOT_INSTALLED_ROLE_ACL_OR_RUNTIME')
    for inv in invariants:gate[inv['INVARIANT']]=inv['VALUE']
    for result in ['ALLOW','DENY','NOT_REACHABLE','REDACTED','CONDITIONALLY_VISIBLE','FUTURE_IMPLEMENTATION_BOUNDARY']:gate['READER_ACL_'+result+'_COUNT']=sum(a['ACL_RESULT']==result for a in acl)
    for k in ['SUPERUSER_USED','BYPASSRLS_USED','PG_READ_ALL_STATS_USED','SECURITY_DEFINER_USED','GENERIC_SQL_USED','DYNAMIC_SQL_USED','ARBITRARY_OBJECT_SELECTION_USED','SQL_TEXT_PARAMETERS_USED','OBJECT_NAME_PARAMETERS_USED','IMPLEMENTATION_PERFORMED','NATIVE_BUILD_PERFORMED','NATIVE_RUNTIME_EXECUTED','SQL_EXECUTED','DATABASE_CONTACTED','V043_EXECUTED','B02_EXECUTED','GIT_ADD','COMMIT','PUSH']:gate[k]='NO'
    seal();out=evaluate();gate.update(TESTS_DISTINCT=out['tests_distinct'],TEST_FAILURES=out['test_failures'],INTEGRITY_FAILURES=out['integrity_failures'])
    if all(inv['VALUE']=='TRUE' for inv in invariants) and gate['READER_EFFECTIVE_ACL_UNRESOLVED']==0 and gate['TRANSITIVE_AUTHORITY_PATHS_FOUND']==gate['TRANSITIVE_AUTHORITY_PATHS_UNRESOLVED']==0 and gate['READER_ACL_ADVERSARIAL_FINDINGS_OPEN']==0 and gate['INDEPENDENT_READER_ACL_REVIEW']=='PASS' and out['test_failures']==out['integrity_failures']==0:
        gate.update(TARGET_BLOCKERS_CLOSED=1,N1_READER_EFFECTIVE_ACL='CLOSED',R5N2A4_2_STATUS='PASS_STATIC_READER_EFFECTIVE_ACL_CLOSED_PHYSICAL_RUNTIME_FUTURE',NEXT_GATE='R5N.2A5_QUALIFICATION_INPUT_RESOLUTION_THEN_SUBSTITUTION_STATIC_WITNESSES')
    else:gate['R5N2A4_2_STATUS']='FAIL_CLOSED_READER_ACL_OPEN'
    put('gate.json',gate);put('test-results.json',out);seal();fresh=evaluate();assert fresh==out,'Fresh sealed verification differs'
    print(json.dumps({k:gate[k] for k in ['UNTRACKED_BEFORE','UNTRACKED_AFTER','UNAUTHORIZED_UNTRACKED_COUNT','READER_GRAPH_NODES_REACHABLE','READER_GRAPH_EDGES_REACHABLE','READER_EFFECTIVE_ACL_ENTRIES_TOTAL','TESTS_DISTINCT','TEST_FAILURES','INTEGRITY_FAILURES','INDEPENDENT_READER_ACL_REVIEW','R5N2A4_2_STATUS']}))
if __name__=='__main__':main()
